const crypto = require('crypto');
return items.map((item) => {
  const body = item.json.body;
  const signature = String(item.json.headers?.['x-mano-signature'] ?? '');
  const expected = 'sha256=' + crypto.createHmac('sha256', $env.N8N_AUTOMATION_WEBHOOK_SECRET).update(JSON.stringify(body)).digest('hex');
  const valid = signature.length === expected.length && crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
  if (!valid) throw new Error('Invalid Mano webhook signature');
  return { json: body };
});

return items.map(({json}) => {
  const labels = {
    'task.queued': 'AI 작업이 대기열에 등록되었습니다',
    'execution.running': 'Codex 실행을 시작했습니다',
    'execution.review': 'Pull Request 검토가 필요합니다',
    'execution.failed': 'AI 실행이 실패했습니다',
    'execution.revision_requested': '수정 요청이 등록되었습니다',
    'execution.merged': 'Pull Request가 병합되었습니다'
  };
  return {json: {...json, notificationTitle: labels[json.eventType] ?? `Mano event: ${json.eventType}`, notificationBody: JSON.stringify(json.payload)}};
});
